-- Receita do Dia — termos de pesquisa afinados (15/10/2026, mesma missão).
-- A revisão de contexto limpo provou que termos genéricos enchiam o carrinho
-- com produtos errados ("papo-seco" dava comida de gato, "azeite" dava atum em
-- azeite). Os termos novos foram testados um a um contra o catálogo do Auchan,
-- Continente, Intermarché e Pingo Doce, e as 14 receitas foram cotadas nos 4
-- (56 carrinhos simulados, sem gravar nada): nenhum produto errado.
-- Onde o catálogo não tem o produto, a receita mudou para o que existe:
-- Caldo verde → Creme de abóbora (não há couve galega no Pingo Doce), Frango
-- assado → Coxas de frango (não há frango inteiro no Pingo Doce), Bifanas no
-- pão → Bifanas com batata frita (não há papo-seco no catálogo); saem o louro,
-- o limão e o fermento (davam arroz da marca Louro, Ice Tea e farinha).
-- "unidades" = quantas embalagens vão para o carrinho (ex.: 3 latas de atum).

UPDATE public.receitas_do_dia r
   SET titulo = v.titulo,
       resumo = v.resumo,
       ingredientes = v.ingredientes,
       passos = v.passos,
       tempo_min = v.tempo_min,
       doses = v.doses
  FROM (VALUES
  ('Bacalhau à Brás', 'Bacalhau à Brás', 'O clássico de sempre, pronto em meia hora.', '[{"nome": "Bacalhau desfiado", "quantidade": "400 g", "pesquisa": "bacalhau desfiado", "unidades": 1}, {"nome": "Batata palha", "quantidade": "1 pacote", "pesquisa": "batata frita palha", "unidades": 1}, {"nome": "Ovos", "quantidade": "6", "pesquisa": "ovos classe m", "unidades": 1}, {"nome": "Cebola", "quantidade": "2", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Azeite", "quantidade": "4 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}, {"nome": "Salsa", "quantidade": "1 molho", "pesquisa": "salsa fresca", "unidades": 1}, {"nome": "Azeitonas pretas", "quantidade": "q.b.", "pesquisa": "azeitonas pretas descaroçadas", "unidades": 1}]'::jsonb, '["Demolha o bacalhau se não vier pronto e escorre bem.", "Aloura a cebola às rodelas finas e o alho no azeite.", "Junta o bacalhau e deixa cozinhar 5 minutos, sempre a mexer.", "Junta a batata palha e, fora do lume, os ovos batidos. Mexe até ficar cremoso.", "Serve com salsa picada e azeitonas."]'::jsonb, 30, 4),
  ('Frango assado com batatas', 'Coxas de frango assadas com batatas', 'Tudo no mesmo tabuleiro, sem complicações.', '[{"nome": "Coxas de frango", "quantidade": "1 kg", "pesquisa": "coxas de frango", "unidades": 1}, {"nome": "Batatas", "quantidade": "1 kg", "pesquisa": "batata branca", "unidades": 1}, {"nome": "Alho", "quantidade": "4 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Vinho branco", "quantidade": "1 copo", "pesquisa": "vinho branco verde", "unidades": 1}, {"nome": "Azeite", "quantidade": "4 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}, {"nome": "Colorau", "quantidade": "1 colher", "pesquisa": "pimentão doce", "unidades": 1}]'::jsonb, '["Tempera as coxas com alho esmagado, colorau, sal, azeite e o vinho branco.", "Corta as batatas em gomos e espalha-as à volta do frango.", "Leva ao forno a 200 °C cerca de 50 minutos, regando com o molho a meio.", "Deixa repousar 5 minutos antes de servir."]'::jsonb, 60, 4),
  ('Caldo verde', 'Creme de abóbora', 'A sopa que aquece a Guarda no inverno.', '[{"nome": "Abóbora", "quantidade": "600 g", "pesquisa": "abóbora manteiga", "unidades": 1}, {"nome": "Batatas", "quantidade": "2", "pesquisa": "batata branca", "unidades": 1}, {"nome": "Cenouras", "quantidade": "2", "pesquisa": "cenoura kg", "unidades": 1}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Azeite", "quantidade": "3 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}]'::jsonb, '["Descasca e corta a abóbora, as batatas, as cenouras, a cebola e o alho.", "Coze tudo em 1,5 L de água com sal durante 25 minutos.", "Tritura até ficar um creme.", "Junta o azeite no fim, fora do lume."]'::jsonb, 35, 4),
  ('Esparguete à bolonhesa', 'Esparguete à bolonhesa', 'O jantar que agrada a miúdos e graúdos.', '[{"nome": "Esparguete", "quantidade": "500 g", "pesquisa": "esparguete", "unidades": 1}, {"nome": "Carne picada", "quantidade": "500 g", "pesquisa": "carne picada de vaca", "unidades": 1}, {"nome": "Polpa de tomate", "quantidade": "1 embalagem", "pesquisa": "polpa de tomate", "unidades": 1}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Azeite", "quantidade": "2 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}, {"nome": "Queijo ralado", "quantidade": "q.b.", "pesquisa": "queijo ralado", "unidades": 1}]'::jsonb, '["Aloura a cebola e o alho picados no azeite.", "Junta a carne picada e deixa alourar, a desfazer com a colher.", "Junta a polpa de tomate, sal e pimenta e deixa apurar 15 minutos.", "Coze o esparguete, escorre e serve com o molho e queijo ralado."]'::jsonb, 35, 4),
  ('Arroz de atum', 'Arroz de atum', 'Rápido, barato e com o que há na despensa.', '[{"nome": "Arroz carolino", "quantidade": "300 g", "pesquisa": "arroz carolino", "unidades": 1}, {"nome": "Atum em lata", "quantidade": "3 latas", "pesquisa": "atum em óleo", "unidades": 3}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Tomate", "quantidade": "2", "pesquisa": "tomate chucha", "unidades": 1}, {"nome": "Azeite", "quantidade": "3 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}, {"nome": "Salsa", "quantidade": "q.b.", "pesquisa": "salsa fresca", "unidades": 1}]'::jsonb, '["Aloura a cebola, o alho e o tomate picados no azeite.", "Junta o arroz, envolve e acrescenta 700 ml de água a ferver com sal.", "Deixa cozinhar 12 minutos em lume brando.", "Junta o atum escorrido, mexe e serve com salsa."]'::jsonb, 25, 4),
  ('Omelete de queijo e fiambre', 'Omelete de queijo e fiambre', 'Jantar em 10 minutos, com salada ao lado.', '[{"nome": "Ovos", "quantidade": "4", "pesquisa": "ovos classe m", "unidades": 1}, {"nome": "Queijo fatiado", "quantidade": "4 fatias", "pesquisa": "queijo fatiado", "unidades": 1}, {"nome": "Fiambre", "quantidade": "4 fatias", "pesquisa": "fiambre fatiado", "unidades": 1}, {"nome": "Alface", "quantidade": "1", "pesquisa": "alface", "unidades": 1}, {"nome": "Tomate", "quantidade": "2", "pesquisa": "tomate chucha", "unidades": 1}, {"nome": "Azeite", "quantidade": "1 colher", "pesquisa": "azeite virgem extra", "unidades": 1}]'::jsonb, '["Bate os ovos com uma pitada de sal.", "Deita numa frigideira com azeite quente em lume médio.", "Quando estiver quase firme, põe o queijo e o fiambre e dobra ao meio.", "Serve com alface e tomate temperados."]'::jsonb, 10, 2),
  ('Sopa de legumes', 'Sopa de legumes', 'A sopa da avó, cheia de cor.', '[{"nome": "Batatas", "quantidade": "3", "pesquisa": "batata branca", "unidades": 1}, {"nome": "Cenouras", "quantidade": "3", "pesquisa": "cenoura kg", "unidades": 1}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Abóbora", "quantidade": "300 g", "pesquisa": "abóbora manteiga", "unidades": 1}, {"nome": "Courgette", "quantidade": "1", "pesquisa": "curgete", "unidades": 1}, {"nome": "Azeite", "quantidade": "3 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}]'::jsonb, '["Descasca e corta os legumes em pedaços.", "Coze tudo em 2 L de água com sal durante 25 minutos.", "Tritura até ficar cremosa.", "Junta o azeite no fim, fora do lume."]'::jsonb, 40, 6),
  ('Bifanas no pão', 'Bifanas com batata frita', 'Sabor de tasca, feitas em casa.', '[{"nome": "Bifanas de porco", "quantidade": "600 g", "pesquisa": "bifanas de porco", "unidades": 1}, {"nome": "Batatas", "quantidade": "1 kg", "pesquisa": "batata branca", "unidades": 1}, {"nome": "Alho", "quantidade": "4 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Vinho branco", "quantidade": "1 copo", "pesquisa": "vinho branco verde", "unidades": 1}, {"nome": "Colorau", "quantidade": "1 colher", "pesquisa": "pimentão doce", "unidades": 1}, {"nome": "Alface", "quantidade": "1", "pesquisa": "alface", "unidades": 1}]'::jsonb, '["Tempera as bifanas com alho, colorau, sal e o vinho branco. Deixa 15 minutos.", "Corta as batatas em palitos e frita-as até ficarem douradas.", "Frita as bifanas num fio de azeite, 2 minutos de cada lado, e junta a marinada para reduzir.", "Serve com a batata frita e alface (ou no pão, se tiveres)."]'::jsonb, 35, 4),
  ('Salada fria de massa com atum', 'Salada fria de massa com atum', 'Para o almoço do dia seguinte ou um dia quente.', '[{"nome": "Massa espiral", "quantidade": "300 g", "pesquisa": "massa espirais", "unidades": 1}, {"nome": "Atum em lata", "quantidade": "2 latas", "pesquisa": "atum em óleo", "unidades": 2}, {"nome": "Milho", "quantidade": "1 lata", "pesquisa": "milho cozido", "unidades": 1}, {"nome": "Ervilhas", "quantidade": "150 g", "pesquisa": "ervilhas", "unidades": 1}, {"nome": "Maionese", "quantidade": "3 colheres", "pesquisa": "maionese", "unidades": 1}, {"nome": "Ovos", "quantidade": "3", "pesquisa": "ovos classe m", "unidades": 1}]'::jsonb, '["Coze a massa e as ervilhas, escorre e deixa arrefecer.", "Coze os ovos 10 minutos e corta-os aos pedaços.", "Junta o atum, o milho e a maionese.", "Envolve tudo e guarda no frigorífico até servir."]'::jsonb, 20, 4),
  ('Pescada no forno com batatas', 'Pescada no forno com batatas', 'Peixe leve, sem cheiro pela casa.', '[{"nome": "Pescada em postas", "quantidade": "800 g", "pesquisa": "postas de pescada", "unidades": 1}, {"nome": "Batatas", "quantidade": "800 g", "pesquisa": "batata branca", "unidades": 1}, {"nome": "Cebola", "quantidade": "2", "pesquisa": "cebola", "unidades": 1}, {"nome": "Tomate", "quantidade": "2", "pesquisa": "tomate chucha", "unidades": 1}, {"nome": "Alho", "quantidade": "3 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Azeite", "quantidade": "5 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}]'::jsonb, '["Corta as batatas às rodelas e coze-as 10 minutos.", "Faz uma cama com batata, cebola e tomate às rodelas num tabuleiro.", "Põe a pescada por cima, com alho, sal e azeite.", "Leva ao forno a 190 °C cerca de 25 minutos."]'::jsonb, 45, 4),
  ('Arroz de frango', 'Arroz de frango', 'Malandrinho, como deve ser.', '[{"nome": "Peito de frango", "quantidade": "500 g", "pesquisa": "peito de frango", "unidades": 1}, {"nome": "Arroz carolino", "quantidade": "300 g", "pesquisa": "arroz carolino", "unidades": 1}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Cenoura", "quantidade": "1", "pesquisa": "cenoura kg", "unidades": 1}, {"nome": "Ervilhas", "quantidade": "100 g", "pesquisa": "ervilhas", "unidades": 1}, {"nome": "Azeite", "quantidade": "3 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}]'::jsonb, '["Corta o frango em cubos e aloura-o no azeite com a cebola e o alho.", "Junta a cenoura às rodelas e as ervilhas.", "Acrescenta o arroz e 900 ml de água a ferver com sal.", "Deixa cozinhar 15 minutos e serve logo, ainda malandrinho."]'::jsonb, 40, 4),
  ('Feijoada rápida', 'Feijoada rápida', 'Conforto num tacho, com feijão já cozido.', '[{"nome": "Feijão encarnado cozido", "quantidade": "2 latas", "pesquisa": "feijão encarnado cozido", "unidades": 2}, {"nome": "Chouriço", "quantidade": "1", "pesquisa": "chouriço de carne", "unidades": 1}, {"nome": "Bacon", "quantidade": "150 g", "pesquisa": "bacon fatiado", "unidades": 1}, {"nome": "Cebola", "quantidade": "1", "pesquisa": "cebola", "unidades": 1}, {"nome": "Alho", "quantidade": "2 dentes", "pesquisa": "alho seco", "unidades": 1}, {"nome": "Cenoura", "quantidade": "2", "pesquisa": "cenoura kg", "unidades": 1}, {"nome": "Arroz carolino", "quantidade": "250 g", "pesquisa": "arroz carolino", "unidades": 1}]'::jsonb, '["Aloura a cebola, o alho, o bacon e o chouriço às rodelas.", "Junta a cenoura e um copo de água e deixa cozinhar 10 minutos.", "Junta o feijão com o caldo e deixa apurar 10 minutos.", "Serve com arroz branco."]'::jsonb, 35, 4),
  ('Panquecas para o lanche', 'Panquecas para o lanche', 'Com mel, fruta ou doce — como preferires.', '[{"nome": "Farinha de trigo", "quantidade": "200 g", "pesquisa": "farinha de trigo", "unidades": 1}, {"nome": "Leite", "quantidade": "300 ml", "pesquisa": "leite meio gordo", "unidades": 1}, {"nome": "Ovos", "quantidade": "2", "pesquisa": "ovos classe m", "unidades": 1}, {"nome": "Açúcar", "quantidade": "2 colheres", "pesquisa": "açúcar branco", "unidades": 1}, {"nome": "Manteiga", "quantidade": "30 g", "pesquisa": "manteiga com sal", "unidades": 1}]'::jsonb, '["Mistura a farinha com o açúcar.", "Junta os ovos, o leite e a manteiga derretida e bate até ficar liso.", "Numa frigideira untada, deita uma concha de massa e vira quando fizer bolhas.", "Serve quentes."]'::jsonb, 20, 4),
  ('Salada de grão com atum', 'Salada de grão com atum', 'Fresca, nutritiva e sem fogão.', '[{"nome": "Grão-de-bico cozido", "quantidade": "2 frascos", "pesquisa": "grão de bico cozido", "unidades": 2}, {"nome": "Atum em lata", "quantidade": "2 latas", "pesquisa": "atum em óleo", "unidades": 2}, {"nome": "Cebola roxa", "quantidade": "1", "pesquisa": "cebola roxa", "unidades": 1}, {"nome": "Ovos", "quantidade": "3", "pesquisa": "ovos classe m", "unidades": 1}, {"nome": "Salsa", "quantidade": "q.b.", "pesquisa": "salsa fresca", "unidades": 1}, {"nome": "Azeite", "quantidade": "4 colheres", "pesquisa": "azeite virgem extra", "unidades": 1}, {"nome": "Vinagre", "quantidade": "2 colheres", "pesquisa": "vinagre de sidra", "unidades": 1}]'::jsonb, '["Passa o grão por água e escorre.", "Coze os ovos 10 minutos e corta-os aos quartos.", "Junta a cebola picada, o atum e a salsa.", "Tempera com azeite, vinagre e sal e envolve tudo."]'::jsonb, 15, 4)
  ) AS v(antigo, titulo, resumo, ingredientes, passos, tempo_min, doses)
 WHERE r.titulo = v.antigo;
